        address vader = address(0x1234);
        address usdv = address(0x5678);
        address vault = address(0x9abc);
        c.init(vader, usdv, vault);
        address recipient = address(0x1111);
        uint amount = 100;
        c.newGrantProposal(recipient, amount);
        bool ok;
        try c.cancelProposal(1, 2) { ok = true; } catch { ok = false; }
